document.addEventListener('DOMContentLoaded', function () {
    var cfg = window.ShortDramaIndexConfig || {};
    var csrfMeta = document.querySelector('meta[name="csrf-token"]');
    var csrf = csrfMeta ? csrfMeta.getAttribute('content') : '';

    function escHtml(s) {
        if (s == null) return '';
        return String(s)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    function escAttr(s) {
        return escHtml(s).replace(/'/g, '&#39;');
    }

    function initShortDramaRailSwipers() {
        if (typeof Swiper === 'undefined') return;
        document.querySelectorAll('.js-sd-rail-swiper').forEach(function (el) {
            if (el.swiper) return;
            var outer = el.closest('.sd-shorts-rail-swiper-wrap');
            var prevBtn = outer ? outer.querySelector('.sd-shorts-rail-nav--prev') : null;
            var nextBtn = outer ? outer.querySelector('.sd-shorts-rail-nav--next') : null;
            var narrow = window.matchMedia('(max-width: 575.98px)').matches;
            var opts = {
                slidesPerView: narrow ? 2.2 : 'auto',
                spaceBetween: narrow ? 6 : 12,
                roundLengths: narrow,
                freeMode: true,
                watchOverflow: true,
                grabCursor: true,
                resistanceRatio: 0.65,
                touchStartPreventDefault: false,
                touchMoveStopPropagation: false,
                nested: true,
                keyboard: { enabled: true }
            };
            if (prevBtn && nextBtn) opts.navigation = { prevEl: prevBtn, nextEl: nextBtn };
            new Swiper(el, opts);
        });
    }

    function syncDiscoverSpacingAfterRail(hasContinue) {
        var discover = document.querySelector('.sd-shorts-discover-block');
        if (!discover) return;
        discover.classList.toggle('sd-shorts-discover-block--after-rail', !!hasContinue);
        discover.classList.toggle('sd-shorts-discover-block--spaced-from-page-title', !hasContinue);
    }

    function destroyContinueSwiper() {
        var swEl = document.getElementById('sd-continue-swiper');
        if (swEl && swEl.swiper) {
            try { swEl.swiper.destroy(true, true); } catch (e) { /* ignore */ }
        }
    }

    function buildContinueSlide(item) {
        var pct = parseInt(item.percentage, 10) || 0;
        var sNum = Math.max(1, parseInt(item.season_number, 10) || 1);
        var eNum = Math.max(1, parseInt(item.episode_number, 10) || 1);
        var progressHtml = pct > 0
            ? '<span class="sd-cw-progress-track" aria-hidden="true"><span class="sd-cw-progress-fill" style="width:' + pct + '%"></span></span>'
            : '';
        var removeAria = (cfg.translations && cfg.translations.removeAria) || 'Remove from continue watching';
        var removeTitle = (cfg.translations && cfg.translations.remove) || 'Remove';

        return '<div class="swiper-slide">' +
            '<div class="sd-cw-wrap" data-cw-wrap data-history-id="' + escAttr(item.history_id) + '">' +
            '<a href="' + escAttr(item.watch_url) + '" class="sd-cw-link">' +
            '<div class="sd-cw-img">' +
            '<img src="' + escAttr(item.thumbnail) + '" alt="' + escAttr(item.drama_title || '') + '" loading="lazy">' +
            '<div class="sd-cw-controls-group">' +
            '<span class="sd-cw-play"><i class="ph-fill ph-play"></i></span>' +
            '<div class="sd-cw-meta"><span class="sd-cw-ep">S' + sNum + ' · E' + eNum + '</span></div>' +
            '</div>' + progressHtml +
            '</div></a>' +
            '<button type="button" class="sd-cw-dismiss" title="' + escAttr(removeTitle) + '" ' +
            'data-dismiss-url="' + escAttr(item.dismiss_url) + '" aria-label="' + escAttr(removeAria) + '">&times;</button>' +
            '</div></div>';
    }

    function buildContinueRailHtml(items) {
        var t = cfg.translations || {};
        var title = cfg.sectionTitle || 'Continue Watching for you';
        var slides = (items || []).map(buildContinueSlide).join('');
        return '<div class="sd-shorts-rail-block" id="sd-continue-block">' +
            '<h2 class="sd-shorts-section-title">' + escHtml(title) + '</h2>' +
            '<div class="sd-shorts-rail-swiper-wrap" id="sd-continue-wrap">' +
            '<button type="button" class="sd-shorts-rail-nav sd-shorts-rail-nav--prev" aria-label="' + escAttr(t.previous || 'Previous') + '">' +
            '<i class="ph ph-caret-left"></i></button>' +
            '<div class="swiper sd-shorts-rail-swiper js-sd-rail-swiper" id="sd-continue-swiper">' +
            '<div class="swiper-wrapper" id="sd-continue-rail">' + slides + '</div></div>' +
            '<button type="button" class="sd-shorts-rail-nav sd-shorts-rail-nav--next" aria-label="' + escAttr(t.next || 'Next') + '">' +
            '<i class="ph ph-caret-right"></i></button></div></div>';
    }

    function hasContinueCards() {
        return !!document.querySelector('#sd-continue-rail [data-cw-wrap]');
    }

    function renderContinueWatchingRail(items) {
        var mount = document.getElementById('sd-continue-mount');
        if (!mount) return;

        destroyContinueSwiper();

        if (!items || !items.length) {
            mount.innerHTML = '';
            syncDiscoverSpacingAfterRail(false);
            return;
        }

        mount.innerHTML = buildContinueRailHtml(items);
        initShortDramaRailSwipers();
        bindCwDismissHandlers();
        syncDiscoverSpacingAfterRail(true);
    }

    function fetchContinueWatchingItems() {
        var url = cfg.continueFeedUrl || (document.getElementById('sd-continue-mount') || {}).getAttribute('data-continue-url');
        if (!url) return Promise.resolve([]);

        return fetch(url, {
            method: 'GET',
            credentials: 'same-origin',
            headers: {
                Accept: 'application/json',
                'X-Requested-With': 'XMLHttpRequest'
            }
        }).then(function (r) {
            if (!r.ok) return [];
            return r.json();
        }).then(function (payload) {
            if (!payload || payload.status === false) return [];
            var data = payload.data;
            if (Array.isArray(data)) return data;
            if (data && Array.isArray(data.items)) return data.items;
            return [];
        }).catch(function () { return []; });
    }

    function refreshContinueWatchingRail() {
        if (!document.getElementById('sd-continue-mount')) return;
        return fetchContinueWatchingItems().then(renderContinueWatchingRail);
    }

    function bindCwDismissHandlers() {
        document.querySelectorAll('.sd-cw-dismiss[data-dismiss-url]').forEach(function (btn) {
            if (btn.dataset.sdCwBound === '1') return;
            btn.dataset.sdCwBound = '1';
            btn.addEventListener('click', function (e) {
                e.preventDefault();
                e.stopPropagation();
                var url = this.getAttribute('data-dismiss-url');
                var wrap = this.closest('[data-cw-wrap]');
                if (!url || !wrap) return;

                this.disabled = true;
                wrap.classList.add('is-removing');

                fetch(url, {
                    method: 'POST',
                    headers: {
                        Accept: 'application/json',
                        'Content-Type': 'application/json',
                        'X-Requested-With': 'XMLHttpRequest',
                        'X-CSRF-TOKEN': csrf
                    },
                    credentials: 'same-origin',
                    body: JSON.stringify({})
                }).then(function (r) {
                    var ct = r.headers.get('content-type') || '';
                    if (ct.indexOf('application/json') === -1) return { ok: false, data: null };
                    return r.json().then(function (data) { return { ok: r.ok, data: data }; });
                }).then(function (res) {
                    if (res.ok && res.data && res.data.status !== false) {
                        var slideEl = wrap.closest('.swiper-slide');
                        if (slideEl) slideEl.remove();
                        else wrap.remove();
                        var swEl = document.getElementById('sd-continue-swiper');
                        var rail = document.getElementById('sd-continue-rail');
                        if (swEl && swEl.swiper) swEl.swiper.update();
                        if (rail && !rail.querySelector('[data-cw-wrap]')) {
                            destroyContinueSwiper();
                            var mount = document.getElementById('sd-continue-mount');
                            if (mount) mount.innerHTML = '';
                            syncDiscoverSpacingAfterRail(false);
                        }
                        var toastMsg = (res.data && res.data.message) ||
                            (cfg.translations && cfg.translations.removed) || '';
                        if (toastMsg && typeof window.successSnackbar === 'function') {
                            window.successSnackbar(toastMsg);
                        }
                        return;
                    }
                    wrap.classList.remove('is-removing');
                    btn.disabled = false;
                }).catch(function () {
                    wrap.classList.remove('is-removing');
                    btn.disabled = false;
                });
            });
        });
    }

    initShortDramaRailSwipers();
    bindCwDismissHandlers();
    syncDiscoverSpacingAfterRail(hasContinueCards());

    var needsRefresh = false;
    try { needsRefresh = sessionStorage.getItem('sd_cw_needs_refresh') === '1'; } catch (e) { /* ignore */ }
    if (needsRefresh) {
        try { sessionStorage.removeItem('sd_cw_needs_refresh'); } catch (e) { /* ignore */ }
        refreshContinueWatchingRail();
    }

    window.addEventListener('load', function () {
        initShortDramaRailSwipers();
        if (needsRefresh || !hasContinueCards()) {
            refreshContinueWatchingRail();
        }
    });

    window.addEventListener('pageshow', function () {
        var stale = false;
        try { stale = sessionStorage.getItem('sd_cw_needs_refresh') === '1'; } catch (e) { /* ignore */ }
        if (stale) {
            try { sessionStorage.removeItem('sd_cw_needs_refresh'); } catch (e) { /* ignore */ }
        }
        if (stale || !hasContinueCards()) {
            refreshContinueWatchingRail();
        } else if (typeof Swiper !== 'undefined') {
            initShortDramaRailSwipers();
        }
    });
});
